enum class weekday {
  monday,
  tuesday,
  wednesday,
  thursday,
  friday,
  saturday,
  sunday,
};

constexpr weekday get_weekday(const civil_second& cs) noexcept {
  constexpr weekday k_weekday_by_mon_off[13] = {
      weekday::monday, weekday::tuesday, weekday::wednesday,
      weekday::thursday, weekday::friday, weekday::saturday,
      weekday::sunday, weekday::monday, weekday::tuesday,
      weekday::wednesday, weekday::thursday, weekday::friday,
      weekday::saturday,
  };
  constexpr int k_weekday_offsets[1 + 12] = {
      -1, 0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4,
  };
  year_t wd = 2400 + (cs.year() % 400) - (cs.month() < 3);
  wd += wd / 4 - wd / 100 + wd / 400;
  wd += k_weekday_offsets[cs.month()] + cs.day();
  return k_weekday_by_mon_off[wd % 7 + 6];
}



constexpr civil_day next_weekday(civil_day cd, weekday wd) noexcept {
  constexpr weekday k_weekdays_forw[14] = {
      weekday::monday, weekday::tuesday, weekday::wednesday,
      weekday::thursday, weekday::friday, weekday::saturday,
      weekday::sunday, weekday::monday, weekday::tuesday,
      weekday::wednesday, weekday::thursday, weekday::friday,
      weekday::saturday, weekday::sunday,
  };
  weekday base = get_weekday(cd);
  for (int i = 0;; ++i) {
    if (base == k_weekdays_forw[i]) {
      for (int j = i + 1;; ++j) {
        if (wd == k_weekdays_forw[j]) {
          return cd + (j - i);
        }
      }
    }
  }
}

constexpr civil_day prev_weekday(civil_day cd, weekday wd) noexcept {
  constexpr weekday k_weekdays_back[14] = {
      weekday::sunday, weekday::saturday, weekday::friday,
      weekday::thursday, weekday::wednesday, weekday::tuesday,
      weekday::monday, weekday::sunday, weekday::saturday,
      weekday::friday, weekday::thursday, weekday::wednesday,
      weekday::tuesday, weekday::monday,
  };
  weekday base = get_weekday(cd);
  for (int i = 0;; ++i) {
    if (base == k_weekdays_back[i]) {
      for (int j = i + 1;; ++j) {
        if (wd == k_weekdays_back[j]) {
          return cd - (j - i);
        }
      }
    }
  }
}

constexpr int get_yearday(const civil_second& cs) noexcept {
  constexpr int k_month_offsets[1 + 12] = {
      -1, 0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334,
  };
  const int feb29 = (cs.month() > 2 && impl::is_leap_year(cs.year()));
  return k_month_offsets[cs.month()] + feb29 + cs.day();
}



